# -*- coding: utf-8 -*-
"""
Generate comprehensive voice scenarios dataset (≥300 scenarios across 12 themes).
Themes:
1. store (магазин и покупки)
2. transit (транспорт и вокзал)
3. work (работа и коллеги)
4. housing (жильё и аренда)
5. doctor (врач и здоровье)
6. documents (документы и банк)
7. dining (кафе, ресторан, быт)
8. interview (собеседование)
9. manager (разговор с руководителем)
10. depot (депо и приёмка)
11. maintenance (обслуживание локомотивов и тормозов)
12. faults (неисправности оборудования и безопасность)
"""

import json
from pathlib import Path

scenarios = []

def add(sid, theme, theme_title, level, title, situation, p_bg, p_ru, t_bg, t_ru, hints, alts, diff, follow_up=None):
    item = {
        "id": f"voice-{sid}",
        "theme": theme,
        "themeTitle": theme_title,
        "level": level,
        "title": title,
        "situation": situation,
        "partnerPromptBg": p_bg,
        "partnerPromptRu": p_ru,
        "targetResponseBg": t_bg,
        "targetResponseRu": t_ru,
        "hints": hints,
        "alternatives": alts,
        "difficulty": diff
    }
    if follow_up:
        item["followUp"] = follow_up
    scenarios.append(item)

